(function(){
  'use strict';
  const C=window.FinanceCore, $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const storeKey='finance-task-studio-project-v1',prefKey='finance-task-studio-remember';
  /* Opened from disk the page is offline. Served by its companion it can run agents after an approval, and the sidebar says which edition this is. */
  const companionServed=()=>location.protocol==='http:'&&location.hostname==='127.0.0.1';
  let p=C.blank(),catalog=C.parseCatalog(window.FinanceCatalog),tab='workspace',active=p.roots[0].id,remember=false,dirty=false,timer;
  try{remember=localStorage.getItem(prefKey)==='yes';if(remember&&localStorage.getItem(storeKey))p=C.parseProject(localStorage.getItem(storeKey));active=p.roots[0].id;}catch{remember=false;}
  const pages=[['workspace','Workspace'],['modes','Failure modes'],['sources','Source evidence'],['roots','Root design'],['economics','Economics'],['review','Review and export'],['experiments','Actual runs'],['playbook','Review gates'],['research','Research catalog']];
  const r=()=>p.roots.find(x=>x.id===active)||p.roots[0];
  /* Extra internal-jargon terms come from a privately loaded evidence module (its lintTerms field). The dashboard hands over only the terms, so a large module is never copied here. Without a module the lint uses its built-in generic terms. */
  const lintOpts=()=>{try{const terms=window.FinanceDashboard?.getLintTerms?.();return Array.isArray(terms)&&terms.length?{extraJargon:terms}:undefined;}catch{return undefined;}};
  const pill=(t,kind='')=>`<span class="pill ${kind}">${esc(t)}</span>`;
  const input=(label,bind,value,hint='',type='text')=>`<label class="field">${esc(label)}<input type="${type}" data-bind="${esc(bind)}" value="${esc(value)}"${type==='number'?' step="any"':''}>${hint?`<small>${esc(hint)}</small>`:''}</label>`;
  const area=(label,bind,value,hint='')=>`<label class="field">${esc(label)}<textarea data-bind="${esc(bind)}">${esc(value)}</textarea>${hint?`<small>${esc(hint)}</small>`:''}</label>`;
  const select=(label,bind,value,options,hint='')=>`<label class="field">${esc(label)}<select data-bind="${esc(bind)}">${options.map(([v,n])=>`<option value="${esc(v)}"${v===value?' selected':''}>${esc(n)}</option>`).join('')}</select>${hint?`<small>${esc(hint)}</small>`:''}</label>`;
  const check=(label,bind,value,hint='')=>`<label class="check"><input type="checkbox" data-bind="${esc(bind)}"${value?' checked':''}><span>${esc(label)}${hint?`<small class="muted"> ${esc(hint)}</small>`:''}</span></label>`;
  const empty=t=>`<div class="empty">${esc(t)}</div>`;
  const btn=(text,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${esc(text)}</button>`;
  const head=(n,title,desc,tag='')=>`<div class="page-head"><div><div class="eyebrow">${esc(n)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${tag?pill(tag):''}</div>`;
  const finding=a=>`<div class="finding ${a.level}"><strong>${esc(a.level)}${a.heuristic?' · heuristic':''}${a.rootId?' · '+esc(p.roots.find(x=>x.id===a.rootId)?.title||a.rootId):''}</strong>${esc(a.message)}</div>`;
  function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='visible'+(error?' error':'');clearTimeout(timer);timer=setTimeout(()=>t.className='',6500);}
  function touch(){dirty=true;p.updatedAt=new Date().toISOString();if(remember)try{localStorage.setItem(storeKey,JSON.stringify(p));}catch{toast('Browser storage is unavailable or full. Save project JSON to keep this work.',true);}status();}
  function status(){if($('#project-title'))$('#project-title').textContent=p.title||'Untitled finance task';if($('#save-state'))$('#save-state').textContent=remember?'Local browser copy enabled · Save JSON for a portable backup':(dirty?'Unsaved session changes · Save project JSON':'Session only · Save project JSON to keep your work');if($('#word-count')){const n=C.words(p.business.prompt);$('#word-count').textContent=n+' / '+C.promptLimit(p)+' words';$('#word-count').className='pill '+(n>C.promptLimit(p)?'red':'');}if($('#guidance-count')){const n=C.words(p.guidance);$('#guidance-count').textContent=n+' words';$('#guidance-count').className='pill '+(n>=800?'red':n>500?'amber':'');}}
  function render(){
    $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">Finance Task Studio</div><div class="brand-sub">Failure modes. Evidence. Economics.</div><nav aria-label="Authoring workflow">${pages.map(([id,label],i)=>`<button class="nav-btn ${tab===id?'active':''}" data-tab="${id}"${tab===id?' aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${label}</button>`).join('')}</nav><div class="sidebar-footer"><span class="privacy-indicator"></span>${companionServed()?'Local by design<br>This editor holds no keys and makes no model calls. Agent runs are on the Agents page, after your approval.':'Offline by design<br>No accounts, keys, or model calls.'}<br>Research links open only when selected.</div></aside><div class="workspace"><header class="topbar"><div><div class="project-name" id="project-title">${esc(p.title)}</div><div class="top-meta" id="save-state"></div></div><div class="top-actions">${btn('New project','new')}${btn('Load JSON','load')}${btn('Save project','save','primary')}</div></header><main id="main" tabindex="-1">${({workspace,modes,sources,roots,economics,review,experiments,playbook:()=>playbook()+researchGates(),research}[tab])()}</main><footer class="footer-note">Authoring drafts require source and business review. Local checks do not verify semantics or predict solver performance.</footer></div></div>`;status();
  }
  function workspace(){const blockers=C.audit(p,lintOpts()).filter(a=>a.level==='blocker').length,hist=p.roots.filter(x=>x.lane==='historical').length;return head('Authoring workspace','Design a decision that matters.','Lock the five failure modes, connect each to a governing rule and a realistic transaction, recompute both interpretations, and make the economic consequence reviewable.','Local / offline')+`<div class="stat-row"><div class="stat"><span class="value">${p.roots.length} / ${C.SET.total}</span><span class="label">Failure modes (${hist} historical, ${p.roots.length-hist} net-new)</span></div><div class="stat"><span class="value">${p.sources.length}</span><span class="label">Task source anchors</span></div><div class="stat"><span class="value">${p.experiments.length}</span><span class="label">Recorded actual runs</span></div></div><div class="grid"><section class="card"><h2>Business context</h2>${input('Project title','p.title',p.title)}<div class="field-row three">${input('Prompt version','p.versions.prompt',p.versions.prompt)}${input('Workbook version','p.versions.workbook',p.versions.workbook)}${input('Evaluator version','p.versions.evaluator',p.versions.evaluator)}</div>${input('Business objective','p.business.objective',p.business.objective,'For example: liquidity through the reimbursement period')}${input('Deliverable','p.business.deliverable',p.business.deliverable,'For example: the cash bridge in the workbook')}${input('Decision to support','p.business.decision',p.business.decision,'For example: whether the planned payments can proceed')}<div class="actions">${btn('Draft business prompt','generate','primary')}<small>Deterministic template; no model.</small></div><hr class="section-divider"><div class="card-title"><h2>Solver-facing prompt</h2><span id="word-count" class="pill"></span></div>${area('Business prompt','p.business.prompt',p.business.prompt,'60-word maximum (the generator drafts 40 or fewer). Retain necessary context, dates, source identity, and the requested deliverable. Do not omit essential information merely to shorten it.')}${p.exportPolicy?`<p class="notice neutral">${esc(p.exportPolicy.reason)} The exact prompt is preserved; no text is truncated.</p>`:''}<p class="footnote">Only this prompt and explicitly supplied filenames/versions enter the solver export. Review them for answer leakage before sharing.</p></section><aside><section class="card dark"><h2>Five modes. One visible consequence each.</h2><p class="muted">Three historical modes from the activity library, two net-new from your own practice. A propagated error can change several outputs while still being one grading root.</p>${[['Lock the set','Import the library pull, select three by Mode ID, add two net-new modes with duplicate checks.'],['Anchor and recompute','Capture the operative excerpt and both branches for each mode.'],['Draft, lint, run','Draft grader guidance from the modes, clear the lint, then test the matched version before adding complexity.']].map(([t,d],i)=>`<div class="step"><span class="n">${i+1}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</section><section class="card"><h2>Start from an illustration</h2><p class="muted">Synthetic projects: invented names, figures, and library records. Nothing here is a task answer or an observed run.</p><div class="actions">${btn('Atlas cash (worked)','example','','data-example="cash"')}${btn('Meridian lending','example','','data-example="lending"')}${btn('Carve-out (incomplete)','example','','data-example="carveout"')}</div><p class="footnote">Loading an illustration replaces the current session after confirmation.</p></section><section class="card"><h2>Local storage</h2>${check('Remember this project in this browser','remember',remember,'Private excerpts will persist on this device.')}<p class="muted">Default is session-only. Project JSON includes private evaluator content. Browser storage on file URLs varies by browser; always keep a JSON backup.</p>${btn('Clear browser copy','clear-storage','small')}<p class="footnote">${blockers} completeness items currently need attention. These checks are not a difficulty score.</p></section></aside></div><section class="card">${area('Project notes','p.notes',p.notes,'Private working notes; never included in solver drafts.')}</section>`;}
  const setCodes=['set-size','historical-count','net-new-count','shortlist-short','library-activity','thesis-empty','mode-id-empty','mode-id-unverified','mode-id-unlisted','duplicate-check','scaffold-unedited'];
  function modes(){const lib=p.library,rank=lib?C.rankLibrary(lib.modes):null,hist=p.roots.filter(x=>x.lane==='historical'),fresh=p.roots.filter(x=>x.lane==='net-new'),t=p.task,findings=C.audit(p,lintOpts()).filter(a=>setCodes.includes(a.code));
    return head('Failure modes','Lock three historical, two net-new.','Historical modes come only from the imported library pull for this activity; net-new modes come from work you did or reviewed. The set is exactly five. Each mode then gets its own root design, evidence anchors, and recomputed economics.',hist.length+' historical · '+fresh.length+' net-new')+`<div class="grid"><section><section class="card"><h2>Task context</h2><p class="muted">Copy these from the task pull. The app never calls the task bundle or library endpoints, and the shared task key never enters it.</p><div class="field-row">${input('Task ID / number','p.task.id',t.id)}${input('Task type(s)','p.task.type',t.type)}</div><div class="field-row">${input('Industry','p.task.industry',t.industry)}${input('Full activity name','p.task.activity',t.activity,'Must match the activity used for the library pull.')}</div></section><section class="card"><div class="card-title"><h2>Stage A · Historical shortlist</h2><div class="actions">${btn('Import library JSON','import-library','primary')}${lib?btn('Clear library','clear-library','small'):''}</div></div>${lib?`<p class="muted">Library for ${esc(lib.activity||'(activity not stated)')}: ${lib.modes.length} returned, ${rank.eligible.length} eligible (approved, uses above zero, numeric average score)${lib.pulledAt?', pulled '+esc(lib.pulledAt):''}.</p>${rank.complete?'':`<div class="notice">Only ${rank.eligible.length} eligible modes. The build requires ten; state the count and stop rather than padding or relaxing eligibility.</div>`}<div class="table-wrap"><table class="shortlist"><thead><tr><th>#</th><th>Mode ID / name</th><th>Mechanism</th><th>Detection guidance</th><th>Avg score</th><th>Uses</th><th>Share</th><th>Overused</th><th></th></tr></thead><tbody>${rank.shortlist.map((m,i)=>{const added=hist.some(x=>x.modeId.trim()===m.modeId);return `<tr><td>${i+1}</td><td><strong>${esc(m.modeId)}</strong><br>${esc(m.name)}</td><td>${esc(m.mechanism)}</td><td>${esc(m.detection)}</td><td>${esc(m.avgTaskScore)}</td><td>${esc(m.uses)}</td><td>${m.usageShare===null?'n/a':esc(m.usageShare)}</td><td>${m.overused?'yes':'no'}</td><td>${added?pill('Selected','green'):btn('Select','select-mode','small',`data-id="${esc(m.modeId)}"${hist.length>=C.SET.historical?' disabled':''}`)}</td></tr>`;}).join('')||'<tr><td colspan="9">No eligible mode.</td></tr>'}</tbody></table></div>`:empty('Pull the library outside this app and import the saved JSON here. Ranking is deterministic: lowest average task score, then most uses, then not overused, then lowest usage share, then Mode ID. Exactly ten are shown; fewer is reported, never padded.')}<p class="footnote">Select exactly three by Mode ID. Selecting creates a historical root prefilled with the returned record; instantiate it in this task on Root design. Removing the root deselects it.</p></section><section class="card"><div class="card-title"><h2>Stage B · Net-new modes</h2>${btn('Add net-new mode','add-mode','primary')}</div><p class="muted">Each net-new mode must come from work you did or reviewed, and must not match, paraphrase, or narrow any of the ten shortlisted modes. Record that comparison in the duplicate check. Candidate roots generated from a loaded package can also be added from the analysis view.</p>${fresh.length?`<div class="list">${fresh.map(x=>`<div class="finding"><strong>${esc(x.title)}</strong>${esc(x.wrongInterpretation||'Plausible wrong approach not recorded.')}<br><small class="muted">Duplicate check: ${esc(x.duplicateCheck||'pending')} · ${esc(x.classification||'unclassified')}</small><div class="actions">${btn('Open','open-root','small',`data-id="${esc(x.id)}"`)}</div></div>`).join('')}</div>`:empty('No net-new modes yet.')}</section>${hist.length?`<section class="card"><h2>Historical selections</h2><div class="list">${hist.map(x=>`<div class="finding"><strong>${esc(x.modeId||'(no Mode ID)')} · ${esc(x.title)}</strong>${esc(x.wrongInterpretation)}<div class="actions">${btn('Open','open-root','small',`data-id="${esc(x.id)}"`)}</div></div>`).join('')}</div></section>`:''}</section><aside><section class="card tint">${area('Failure mode thesis','p.thesis',p.thesis,'One paragraph on how the five modes form one coherent, finance-grounded challenge.')}</section><section class="card"><h2>Set status</h2><div class="list">${findings.map(finding).join('')||empty('Five modes recorded: three historical from the shortlist and two net-new with duplicate checks.')}</div></section><section class="card"><h2>Record contract</h2><p class="muted">Deliverable context, failure or judgment point, triggering condition, plausible wrong approach, consequence, detection method, corrective action, expected model behavior, classification. A mode is usable only when the wrong path is plausible, the consequence is observable, and a grader can tell the correct behavior apart.</p></section></aside></div>`;}
  function sources(){return head('Source evidence','Make the rule traceable.','Capture task evidence here. This private evidence store is separate from the public research catalog.')+`<div class="notice neutral">Record exact excerpts and locations, not entire private workbooks. Mark a source supplied only when the solver will actually receive that version. The app does not attach or upload files.</div><div class="card-title"><h2>${p.sources.length} source anchors</h2>${btn('Add source anchor','add-source','primary')}</div><div class="source-grid">${p.sources.map(s=>`<section class="card"><div class="card-title"><h2>${esc(s.title||'New source')}</h2>${pill(s.reviewStatus,s.reviewStatus==='reviewed'?'green':'amber')}</div>${input('Source title','s.'+s.id+'.title',s.title)}<div class="field-row">${input('Exact supplied filename','s.'+s.id+'.file',s.file)}${input('Source version','s.'+s.id+'.version',s.version)}</div><div class="field-row">${input('Page / section','s.'+s.id+'.page',s.page)}${input('Sheet / cell / range','s.'+s.id+'.cell',s.cell)}</div><div class="field-row">${input('Effective / source date','s.'+s.id+'.date',s.date,'Use an ISO date or unambiguous source period.')} ${input('Authority / precedence','s.'+s.id+'.authority',s.authority)}</div>${area('Exact source excerpt','s.'+s.id+'.excerpt',s.excerpt,'Private evaluator evidence. Do not summarize away the operative condition.')}${select('Source review','s.'+s.id+'.reviewStatus',s.reviewStatus,[['pending','Pending review'],['reviewed','Author marked reviewed'],['superseded','Superseded — do not govern']])}${check('This exact file version will be supplied to the solver','s.'+s.id+'.suppliedToSolver',s.suppliedToSolver)}${btn('Remove anchor','remove-source','small danger',`data-id="${esc(s.id)}"`)}</section>`).join('')||empty('Add the operative source excerpt before building the root.')}</div>`;}
  function rootbar(){return `<div class="rootbar"><label for="active-root">Failure mode</label><select id="active-root" data-control="active-root">${p.roots.map(x=>`<option value="${esc(x.id)}"${x.id===r().id?' selected':''}>${esc(x.title)}${x.lane==='historical'?' ['+esc(x.modeId||'historical')+']':' [net-new]'}</option>`).join('')}</select>${btn('Add net-new mode','add-root')}${btn('Remove','remove-root','danger small',p.roots.length===1?'disabled':'')}</div>`;}
  function anchors(ids,bind){return p.sources.length?`<div class="list">${p.sources.map(s=>`<label class="check source-anchor"><input type="checkbox" data-anchor="${esc(bind)}" value="${esc(s.id)}"${ids.includes(s.id)?' checked':''}><span><strong>${esc(s.title||'Untitled source')} · ${esc(s.version||'No version')}</strong><small>${esc([s.file,s.page,s.cell].filter(Boolean).join(' / '))} · ${esc(s.reviewStatus)}</small></span></label>`).join('')}</div>`:empty('Add source evidence first.');}
  function roots(){const x=r(),m=catalog.mechanisms.find(m=>m.id===x.mechanism);return head('Root design','Where does the judgment change?','Instantiate the failure mode in this task: connect the rule and transaction facts, then record how the wrong path shows up and how a grader tells it apart.')+rootbar()+`<div class="grid"><section class="card">${input('Mode title','r.title',x.title)}<div class="field-row">${select('Lane','r.lane',x.lane,[['net-new','Net-new (from own experience)'],['historical','Historical (library Mode ID)']])}${input('Library Mode ID','r.modeId',x.modeId,x.lane==='historical'?'Must be one of the ten shortlisted modes.':'Leave blank for a net-new mode.')}</div><div class="field-row">${select('Finance mechanism','r.mechanism',x.mechanism,[[x.mechanism,'Current: '+(m?.title||x.mechanism)],...catalog.mechanisms.filter(m=>m.id!==x.mechanism).map(m=>[m.id,m.title])])}${input('Causal group ID','r.causalGroup',x.causalGroup,'Use the same ID for consequences of the same root; count them once.')}</div><div class="notice neutral">${esc(m?.designQuestion||'Describe the source-resolvable business judgment.') }<div class="footnote">${esc(m?.status||'Authoring mechanism; source mapping needs review')}</div></div>${area('Governing rule','r.governingRule',x.governingRule,'State the operative rule and why its source has authority.')}${area('Edge-case transaction facts','r.facts',x.facts,'Facts that make scope, timing, definitions, or constraints matter.')}<h3>Governing anchors</h3>${anchors(x.sourceIds,'root')}<hr class="section-divider">${area('Correct interpretation','r.correctInterpretation',x.correctInterpretation)}${area('Plausible wrong approach','r.wrongInterpretation',x.wrongInterpretation,'Record one causal error. Additional downstream wrong numbers belong to this same root.')}<hr class="section-divider"><h3>Failure-mode record</h3>${area('Triggering condition','r.triggeringCondition',x.triggeringCondition,'When the issue appears in this task’s files.')}${area('Detection method','r.detectionMethod',x.detectionMethod,'The observable signal in the output that separates the wrong path from the correct one.')}${area('Corrective action','r.correctiveAction',x.correctiveAction,'What should happen instead.')}<div class="field-row">${select('Expected model behavior','r.expectedBehavior',x.expectedBehavior,[['','Not set'],['solve','Solve'],['reconcile','Reconcile'],['push-back','Push back']])}${select('Classification','r.classification',x.classification,[['','Not set'],['strict-error','Strict error'],['judgment-call','Judgment-call divergence']])}</div>${x.lane==='net-new'?area('Duplicate check','r.duplicateCheck',x.duplicateCheck,'How this differs from each shortlisted historical mode in trigger, wrong approach, consequence, and detection.'):''}${x.libraryRecord?`<details><summary>Returned library record</summary><pre>${esc(x.libraryRecord)}</pre></details>`:''}<div class="actions">${btn('Scaffold blanks from mechanism','scaffold')}<small>Fills only empty record fields from the catalog mechanism, marked as hypotheses.</small></div></section><aside><section class="card">${area('Acceptable source-supported variations','r.acceptableVariations',x.acceptableVariations,'Include equivalent methods and defensible alternatives; do not require a favored layout.')}${area('Tolerance rationale','r.toleranceRationale',x.toleranceRationale,'Justify absolute/relative tolerances from units, input precision, and rounding policy.')}${area('Unresolved ambiguity','r.ambiguity',x.ambiguity,'Leave blank only after ambiguity is resolved. Multiple defensible answers must be accepted.')}${area('Assumptions requiring support','r.assumptions',x.assumptions)}${area('Resolution / source support','r.resolution',x.resolution)}${select('Interpretation review','r.reviewStatus',x.reviewStatus,[['pending','Pending author review'],['reviewed','Author marked reviewed for this design']],'Content edits reset this status. This is a working review flag, not an official human attestation.')}</section><section class="card"><h2>Author-identified concerns</h2>${check('Prompt teaches the method or leaks the answer','r.checks.teaching',x.checks.teaching)}${check('Same root is counted more than once','r.checks.doubleCount',x.checks.doubleCount)}${check('Error does not change a material outcome','r.checks.outcomeIrrelevant',x.checks.outcomeIrrelevant)}${check('An assumption lacks source support','r.checks.unsupported',x.checks.unsupported)}<p class="footnote">These are explicit author flags. Automated wording checks are only heuristics.</p></section></aside></div>`;}
  const calculatorFields={cash:[['facility','Facility amount'],['fraction','Restricted availability fraction'],['asOf','As-of date','date'],['clearDate','Reimbursement clearance date','date'],['releaseDate','Confirmed business-day release date','date'],['opening','Opening usable cash'],['fundedDraw','Confirmed funded draw'],['otherInflows','Other confirmed inflows'],['outflows','Due cash outflows'],['unit','Currency / source units','text']],ceiling:[['constraints','All derived upper price bounds','textarea'],['unit','Price units','text']],dividend:[['budget','Usable cash budget'],['price','Trade price per share'],['loanShares','Shares on loan on record date'],['dividend','Dividend per share']],fixed:[['a','Non-circular component a'],['b','Feedback coefficient b'],['unit','Units','text']]};
  function economics(){const x=r(),o=p.oracle;return head('Economic consequence','Recompute the decision.','Compare both branches in consistent units. Numeric checks are deterministic; they do not establish that the financial interpretation is correct.')+rootbar()+`<div class="grid"><section><div class="card"><div class="card-title"><h2>Correct and wrong outputs</h2>${btn('Add output','add-output','primary')}</div>${x.outputs.map(v=>{let c;try{c=C.compare(v);}catch{}return `<div class="output-block"><hr class="section-divider">${input('Output label','o.'+v.id+'.label',v.label)}<div class="field-row three">${input('Correct reading','o.'+v.id+'.correct',v.correct)}${input('Wrong reading','o.'+v.id+'.wrong',v.wrong)}${input('Units','o.'+v.id+'.unit',v.unit)}</div><div class="field-row">${input('Absolute tolerance','o.'+v.id+'.absTolerance',v.absTolerance)}${input('Relative tolerance (fraction)','o.'+v.id+'.relTolerance',v.relTolerance,'0.001 means 0.1%; effective tolerance is the greater of absolute and relative.')}</div><div class="field-row">${select('Decision passes when output is','o.'+v.id+'.direction',v.direction,[['at-least','At least threshold'],['at-most','At most threshold']])}${input('Decision threshold (optional)','o.'+v.id+'.threshold',v.threshold)}</div><div class="comparison-live" data-comparison="${esc(v.id)}">${comparison(v)}</div>${area('Recomputation and output location','o.'+v.id+'.calculation',v.calculation,'Include the formula, input values, intermediate anchors, and exact tab/cell of the requested output.')}<details><summary>Calculation source anchors (${v.sourceIds.length})</summary>${anchors(v.sourceIds,'output:'+v.id)}</details>${btn('Remove output','remove-output','small danger',`data-id="${esc(v.id)}"`)}</div>`;}).join('')||empty('Add an output or use a helper to record a calculation.')}</div><section class="card">${area('Headline decision under correct reading','r.headlineCorrect',x.headlineCorrect)}${area('Headline decision under wrong reading','r.headlineWrong',x.headlineWrong)}${btn('Refresh comparisons','refresh')}</section></section><aside><section class="card tint"><h2>Transparent calculation helpers</h2><p class="muted">Enter sourced inputs. Every result shows its equation and limits. No workbook parsing or semantic inference.</p>${select('Helper','oracle.kind',o.kind,[['cash','Actual cash bridge'],['ceiling','Joint whole-cent ceiling'],['dividend','Record-date dividend capacity'],['fixed','Affine fixed point']])}${calculatorFields[o.kind].map(([k,l,t])=>t==='textarea'?area(l,'calc.'+k,o.inputs[k]||'','One non-negative bound per line. Up to 8 decimal places.'):input(l,'calc.'+k,o.inputs[k]||'',k==='fundedDraw'?'An available facility is not necessarily drawn. Enter actual funded cash.':'',t==='date'?'date':'text')).join('')}${btn('Calculate','calculate','primary')}${o.result?`<div id="calculator-result"><hr class="section-divider"><h3>${esc(o.result.label)}</h3><div class="metric">${esc(fmt(o.result.value))} <small>${esc(o.result.unit)}</small></div><p class="trace">${esc(o.result.formula)}</p><dl class="trace">${Object.entries(o.result.details).map(([k,v])=>`<dt>${esc(k.replace(/([A-Z])/g,' $1'))}</dt><dd>${esc(typeof v==='number'?fmt(v):v)}</dd>`).join('')}</dl><p class="footnote">${esc(o.result.caveat)}</p>${btn('Record as correct output','use-calculation')}</div>`:''}</section><div class="notice">A supplied reference number is not a recomputation. The illustrations label every placeholder that still needs an equation or input.</div></aside></div>`;}
  function lintList(){return C.lintGuidance(p.guidance,lintOpts()).map(finding).join('')||empty('No lint finding. Substance still needs the author.');}
  function review(){const checks=C.audit(p,lintOpts()),blockers=checks.filter(a=>a.level==='blocker'),count=C.words(p.business.prompt);let solver;try{solver=C.solverDraft(p);}catch{}return head('Review and export','Inspect the audiences.','Check source-resolvable correctness, tolerances, and materiality. Draft and lint the grader guidance, then review the exact exported content before sharing.',blockers.length+' open completeness items')+`<div class="grid equal"><section class="card"><div class="card-title"><h2>Solver draft</h2>${pill('Public-facing content')}</div><div class="preview">${esc(p.business.prompt||'Write a business prompt in Workspace.')}</div><p class="muted">${count} / ${C.promptLimit(p)} words.${p.exportPolicy?' Explicit author-approved project exception.':''} No root interpretations, private excerpts, correct outputs, experiment notes, or catalog are added.</p><h3>Explicit file manifest</h3>${solver?.suppliedFileManifest.length?`<ul>${solver.suppliedFileManifest.map(s=>`<li>${esc(s.file)} · ${esc(s.version)}</li>`).join('')}</ul>`:empty('No files are marked supplied. Attach the necessary source files separately.')}<div class="actions">${btn('Export solver JSON','solver-json','primary')}${btn('Export solver text','solver-text')}</div><p class="footnote">Typed prompt text and filenames can themselves reveal an answer; inspect them manually. The export is deliberately allowed as a draft before all review items are resolved.</p></section><section class="card"><div class="card-title"><h2>Evaluator draft</h2>${pill('Grader-only / private','amber')}</div><p class="muted">Includes the failure-mode set, root records, source excerpts, acceptable variations, calculation traces, review flags, grader guidance with its lint, and actual run records.</p><div class="notice neutral">Count a propagated causal error once. Accept source-supported alternatives. Do not force a failure or infer difficulty from an untested design.</div><div class="actions">${btn('Export evaluator JSON','evaluator-json','primary')}${btn('Export evaluator text','evaluator-text')}</div><details><summary>Inspect exact evaluator JSON</summary><pre>${esc(JSON.stringify(C.evaluatorDraft(p,lintOpts()),null,2))}</pre></details><p class="footnote">Official human-only FailureAnalysis and GraderAnalysis fields are never generated. This app does not submit to Studio.</p></section></div><section class="card"><div class="card-title"><h2>Grader guidance draft</h2><span id="guidance-count" class="pill"></span></div>${area('Grader guidance','p.guidance',p.guidance,'Plain prose to a sharp finance colleague: what the task is, which files govern, the real failure modes, a few anchors. About 650 words or fewer; 800 is returned.')}<div class="actions">${btn('Draft from failure modes','draft-guidance')}${btn('Clean text','clean-guidance')}${btn('Export guidance text','guidance-text','primary')}</div><div class="list" id="guidance-lint">${lintList()}</div><p class="footnote">Lint is heuristic. It cannot judge whether a failure mode is finance-specific or whether the numbers agree with the answer file.</p></section><section class="card"><div class="card-title"><h2>Author-side exports</h2>${pill('Private','amber')}</div><p class="muted">The failure-mode records in the record-contract shape and the persistent working document. Both are working material, never solver-facing.</p><div class="actions">${btn('Export failure-mode records','modes-text','primary')}${btn('Export working document','working-doc')}</div></section><section class="card"><div class="card-title"><h2>Review findings</h2>${btn('Recheck','refresh','small')}</div><p class="muted">Completeness checks inspect structure and numbers. Items labeled heuristic only suggest where an author should look. No “all clear” label establishes semantic correctness.</p><div class="list">${checks.map(finding).join('')||empty('Structural checks found no issue. An author must still verify every source and interpretation.')}</div></section>`;}
  function experiments(){return head('Actual runs','Evidence beats a difficulty claim.','Record observed results with actual run IDs and exact versions. This tool never runs a solver, invents a score, or predicts a failure percentage.')+`<div class="grid"><section class="card"><h2>Record an observed run</h2><form id="run-form"><div class="field-row">${formInput('Actual run ID','runId')}${formInput('Run date','date','','date')}</div>${formInput('Model / environment label','model')}<div class="field-row three">${formInput('Prompt version','promptVersion',p.versions.prompt)}${formInput('Workbook version','workbookVersion',p.versions.workbook)}${formInput('Evaluator version','evaluatorVersion',p.versions.evaluator)}</div><div class="field-row">${formInput('Observed score (optional)','score')}${formInput('Score maximum','scoreMax','')}</div><p class="footnote">For 93.1%, enter 93.1 and 100. Leave both score fields blank if no score exists.</p>${formInput('Evidence file / result location','evidence')}<label class="field">Observed explanation<select name="classification">${C.classifications.map(x=>`<option value="${x}">${esc(x.replace(/-/g,' '))}</option>`).join('')}</select></label><h3>Failure modes actually observed</h3>${p.roots.map(x=>`<label class="check"><input type="checkbox" name="rootFailures" value="${esc(x.id)}">${esc(x.title)} · ${esc(x.causalGroup)}</label>`).join('')}<label class="field">Observation notes<textarea name="notes" placeholder="What was actually observed? Separate model error from task design or grading behavior."></textarea></label><label class="check"><input type="checkbox" name="attachSnapshot">Attach this current design snapshot only if it was used in this run.</label><button type="submit" class="primary">Save actual run record</button></form></section><aside><section class="card tint"><h2>Keep explanations distinct</h2><p class="muted">A high score can reflect a solved task, method dictated in the brief, a named trap, permissive grading, broad shallow criteria, plain lookup, or grader leniency. These are not automatically model failures.</p><p class="muted">An older score belongs to that older prompt, workbook, and evaluator. Test the current version once before adding complexity.</p></section><section class="card"><h2>No synthetic runs</h2><p class="muted">The illustrations carry no experiment records. Run IDs and evidence locations are user-entered references; the app does not contact the run service to verify them.</p><p class="muted">Planned failure modes are never reused as observed evidence. Only a matched actual run can show which modes surfaced.</p></section></aside></div><section class="card"><h2>Run ledger</h2>${p.experiments.length?`<div class="table-wrap"><table><thead><tr><th>Run / date</th><th>Model / versions</th><th>Observed score</th><th>Root evidence</th><th>Comparison</th><th></th></tr></thead><tbody>${p.experiments.map(e=>`<tr><td><strong>${esc(e.runId)}</strong><br>${esc(e.date)}<br><small>${esc(e.evidence)}</small></td><td>${esc(e.model)}<br><small>${esc(Object.values(e.versions).join(' / '))}</small></td><td>${e.score!==''?esc(e.score)+' / '+esc(e.scoreMax):'Not scored'}</td><td>${esc(e.classification.replace(/-/g,' '))}<br><small>${e.rootFailures.map(id=>esc(p.roots.find(x=>x.id===id)?.title||id+' (historical)')).join(', ')||'No root failures recorded'}</small><details><summary>Notes</summary>${esc(e.notes)}</details></td><td>${pill(e.snapshot&&e.snapshot===C.snapshot(p)?'Recorded snapshot matches':Object.keys(p.versions).every(k=>p.versions[k]===e.versions[k])?'Labels match; content unconfirmed':'Version mismatch',e.snapshot&&e.snapshot===C.snapshot(p)?'green':'amber')}</td><td>${btn('Remove','remove-run','small danger',`data-id="${esc(e.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No actual runs recorded. Current difficulty is unknown.')}</section>`;}
  function formInput(label,name,value='',type='text'){return `<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}"></label>`;}
  function playbook(){const book=window.FinancePlaybook;return head('User-provided design guidance','Use the playbook with judgment.','These coverage gates adapt the supplied playbook into fair, reviewable design checks. They are author judgments, not automatic validation.')+`<section class="card"><h2>${esc(book.title)}</h2><p class="muted">${esc(book.provenance)}</p><div class="notice">${esc(book.limits)}</div><p>Keep necessary clarity and accessible governing evidence. Interpretive depth is useful; hidden expectations and forced sub-60 grading are not design goals.</p></section><div class="source-grid">${book.gates.map(g=>{const value=p.gates[g.id]||{status:'pending',notes:''};return `<section class="card"><div class="card-title"><h2>${esc(g.title)}</h2>${pill('Page '+g.page)}</div><p class="muted">${esc(g.question)}</p>${select('Author assessment','gate.'+g.id+'.status',value.status,[['pending','Not reviewed'],['addressed','Addressed for this design'],['needs-work','Needs work'],['not-applicable','Not applicable — explain below']])}${area('Evidence / rationale','gate.'+g.id+'.notes',value.notes,'Point to the prompt, source anchor, output, or actual run record.')}</section>`;}).join('')}</div>`;}
  function research(){return head('Research catalog','Find mechanisms, preserve caveats.','Research can suggest what to investigate. It cannot validate a private task, prove a correct interpretation, or predict a current model score.')+`<div class="notice neutral">This catalog contains public research metadata only. Task source excerpts and the user-provided playbook stay separate. Exporting this catalog does not export your project.</div><div class="card-title"><div class="actions">${btn('Import research JSON','import-catalog')}${btn('Export catalog JSON','export-catalog')}</div>${pill(catalog.sources.length+' source records')}</div><label class="field">Filter by title, mechanism, or caveat<input class="search" id="research-search" placeholder="Search the catalog"></label><section class="card"><h2>Mechanism design questions</h2><div id="mechanism-list">${catalog.mechanisms.map(m=>`<details class="research-item" data-search="${esc((m.title+' '+m.description+' '+m.designQuestion).toLowerCase())}"><summary>${esc(m.title)}</summary><p>${esc(m.description)}</p><p><strong>${esc(m.designQuestion)}</strong></p><p class="muted">Plausible wrong reading: ${esc(m.wrongReading)}<br>Decision consequence: ${esc(m.decisionImpact)}</p>${mechanismDetail(m)}<p class="muted">${esc(m.status)}${m.sourceIds.length?' · Sources: '+esc(m.sourceIds.join(', ')):''}</p></details>`).join('')}</div></section><div class="source-grid">${catalog.sources.map(s=>`<section class="card research-card research-item" data-search="${esc((s.title+' '+s.summary+' '+s.limits).toLowerCase())}"><div class="card-title"><h2>${esc(s.title)}</h2>${pill(s.status,s.status==='verified'?'green':'amber')}</div><p class="muted">${esc(s.version)}</p><p>${esc(s.summary)}</p>${s.claims.length?`<ul>${s.claims.map(c=>`<li class="muted">${esc(c)}</li>`).join('')}</ul>`:''}<p class="limits">${esc(s.limits)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open public source</a></section>`).join('')}</div><p class="footnote">Catalog date: ${esc(catalog.updatedAt)}. “Verified” refers to the supplied research review scope and its caveats, not independent verification by this app.</p>`;}
  function comparison(v){try{const c=C.compare(v);return `<div class="notice ${c.decisionChanges?'':'neutral'}">Wrong minus correct: <strong>${esc(fmt(c.delta))} ${esc(v.unit)}</strong>. Effective tolerance: ${esc(fmt(c.tolerance))}.${c.correctDecision!==null?` Correct branch: ${c.correctDecision?'passes':'fails'}; wrong branch: ${c.wrongDecision?'passes':'fails'}. ${c.decisionChanges?'Decision changes.':'No threshold crossing.'}`:''}</div>`;}catch(e){return `<p class="muted">Comparison incomplete: ${esc(e.message)}</p>`;}}
  function mechanismDetail(m){return [['Required facts',m.requirements],['Fairness checks',m.fairness],['Leakage checks',m.leakage],['Primary-source anchors',m.evidence]].map(([label,items])=>items?.length?`<h3>${esc(label)}</h3><ul>${items.map(t=>`<li class="muted">${esc(t)}</li>`).join('')}</ul>`:'').join('');}
  function researchGates(){const q=window.FinanceResearchGates;return `<hr class="section-divider"><div class="page-head"><div><div class="eyebrow">Research acceptance checklist</div><h2>Sixteen source-grounded review gates</h2><p>${esc(q.evidence_boundary)}</p></div></div><div class="source-grid">${q.gates.map(g=>{const key='research-'+g.id,value=p.gates[key]||{status:'pending',notes:''};return `<section class="card"><h3>${esc(g.question)}</h3><p class="muted">Evidence: ${esc(g.required_evidence)}</p>${select('Author assessment','gate.'+key+'.status',value.status,[['pending','Not reviewed'],['addressed','Addressed for this design'],['needs-work','Needs work'],['not-applicable','Not applicable — explain below']])}${area('Evidence / rationale','gate.'+key+'.notes',value.notes)}</section>`;}).join('')}</div><section class="card"><h2>Validation workflow</h2><ol>${q.validation_workflow.map(t=>`<li><p class="muted">${esc(t)}</p></li>`).join('')}</ol><p class="footnote">Addressed gate flags reset after substantive design edits; their rationale is retained. The app records review and observed results; it does not execute models or submit tasks. Retain valid financial semantics regardless of whether performance falls.</p></section>`;}
  function fmt(x){return Number.isFinite(x)?x.toLocaleString('en-US',{maximumFractionDigits:8}):String(x);}
  function invalidateGates(){Object.values(p.gates).forEach(g=>{if(g.status==='addressed')g.status='pending';});}
  function invalidate(){p.roots.forEach(x=>x.reviewStatus='pending');invalidateGates();}
  function setBinding(binding,value){const parts=binding.split('.');const group=parts.shift();
    if(group==='remember'){remember=!!value;try{if(remember)localStorage.setItem(prefKey,'yes');else{localStorage.removeItem(prefKey);localStorage.removeItem(storeKey);}}catch{remember=false;toast('Browser storage unavailable. Use project JSON.',true);}touch();return;}
    let target;
    if(group==='p'){target=p;if(!['notes','title','guidance','thesis','task'].includes(parts[0]))invalidate();}
    else if(group==='r'){target=r();if(parts.join('.')!=='reviewStatus'){target.reviewStatus='pending';invalidateGates();}}
    else if(group==='s'){target=p.sources.find(s=>s.id===parts.shift());invalidate();if(parts[0]!=='reviewStatus')target.reviewStatus='pending';}
    else if(group==='o'){target=r().outputs.find(o=>o.id===parts.shift());r().reviewStatus='pending';invalidateGates();}
    else if(group==='oracle'){target=p.oracle;if(parts[0]==='kind'){p.oracle={kind:value,inputs:{},result:null};touch();render();return;}}
    else if(group==='calc'){target=p.oracle.inputs;p.oracle.result=null;if($('#calculator-result'))$('#calculator-result').innerHTML='<p class="notice">Inputs changed. Calculate again to get a current result.</p>';}
    else if(group==='gate'){const id=parts.shift();target=p.gates[id]??={status:'pending',notes:''};}
    if(!target)return;while(parts.length>1)target=target[parts.shift()];target[parts[0]]=value;touch();const rootReview=document.querySelector('[data-bind="r.reviewStatus"]');if(rootReview)rootReview.value=r().reviewStatus;if(group==='s'){const sourceReview=document.querySelector('[data-bind="s.'+target.id+'.reviewStatus"]');if(sourceReview){sourceReview.value=target.reviewStatus;const badge=sourceReview.closest('.card').querySelector('.pill');if(badge){badge.textContent=target.reviewStatus;badge.className='pill '+(target.reviewStatus==='reviewed'?'green':'amber');}}}if(group==='o'){const el=document.querySelector('[data-comparison="'+target.id+'"]');if(el)el.innerHTML=comparison(target);}if(group==='p'&&parts[0]==='guidance'){const el=$('#guidance-lint');if(el)el.innerHTML=lintList();}if(group==='r'&&['mechanism','lane'].includes(parts[0]))render();
  }
  function download(filename,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function replaceProject(next){p=next;active=p.roots[0].id;tab='workspace';touch();render();}
  const filename=suffix=>(p.title||'finance-task').replace(/[^a-z0-9-]+/gi,'-').slice(0,80)+'-'+suffix;
  function newRoot(lane='net-new'){const x=C.root();x.causalGroup=x.id;x.lane=lane;p.roots.push(x);active=x.id;invalidateGates();touch();return x;}
  function evaluatorText(e){let lines=['EVALUATOR DRAFT — PRIVATE',e.title,'Task: '+JSON.stringify(e.task),'Versions: '+JSON.stringify(e.versions),e.notice,'','FAILURE MODE SET',JSON.stringify(e.failureModeSet,null,2),'','GRADER GUIDANCE ('+e.graderGuidance.wordCount+' words)',e.graderGuidance.text||'(none)','Guidance lint: '+JSON.stringify(e.graderGuidance.lint,null,2),''];for(const x of e.rootRecords){lines.push('ROOT: '+x.title+' ['+x.lane+(x.modeId?' '+x.modeId:'')+']','Causal group: '+x.causalGroup,'Mechanism: '+x.mechanism,'Governing rule: '+x.governingRule,'Facts: '+x.facts,'Triggering condition: '+x.triggeringCondition,'Correct interpretation: '+x.correctInterpretation,'Plausible wrong approach: '+x.wrongInterpretation,'Detection method: '+x.detectionMethod,'Corrective action: '+x.correctiveAction,'Expected model behavior: '+x.expectedBehavior,'Classification: '+x.classification,'Duplicate check: '+x.duplicateCheck,'Acceptable variations: '+x.acceptableVariations,'Tolerance rationale: '+x.toleranceRationale,'Ambiguity: '+x.ambiguity,'Assumptions: '+x.assumptions,'Resolution: '+x.resolution,'Correct headline: '+x.headlineCorrect,'Wrong headline: '+x.headlineWrong,'Outputs: '+JSON.stringify(x.outputs,null,2),'Anchors: '+x.sourceIds.join(', '),'');}lines.push('SOURCE ANCHORS',JSON.stringify(e.sourceAnchors,null,2),'REVIEW FINDINGS',JSON.stringify(e.checks,null,2),'AUTHOR REVIEW GATES',JSON.stringify(e.authorReviewGates,null,2),'ACTUAL RUNS',JSON.stringify(e.experiments,null,2),'CALCULATOR',JSON.stringify(e.calculator,null,2));return lines.join('\n');}
  document.addEventListener('input',e=>{if(e.target.dataset.bind)setBinding(e.target.dataset.bind,e.target.type==='checkbox'?e.target.checked:e.target.value);if(e.target.id==='research-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.research-item').forEach(el=>el.hidden=!el.dataset.search.includes(q));}});
  document.addEventListener('change',e=>{if(e.target.dataset.control==='active-root'){active=e.target.value;render();}if(e.target.dataset.anchor){let ids=e.target.dataset.anchor==='root'?r().sourceIds:r().outputs.find(o=>o.id===e.target.dataset.anchor.split(':')[1]).sourceIds;if(e.target.checked&&!ids.includes(e.target.value))ids.push(e.target.value);else if(!e.target.checked)ids.splice(ids.indexOf(e.target.value),1);r().reviewStatus='pending';invalidateGates();touch();}});
  document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.tab){tab=t.dataset.tab;render();$('#main').focus();return;}const action=t.dataset.action;if(!action)return;try{
    if(action==='new'){if(confirm('Start a new project? Save project JSON first if you need this session.'))replaceProject(C.blank());}
    if(action==='load')$('#project-file').click();
    if(action==='save'){download(filename('project.json'),JSON.stringify(p,null,2));dirty=false;status();toast('Project JSON downloaded. It includes private evaluator evidence.');}
    if(action==='generate'){p.business.prompt=C.generatePrompt(p.business);invalidate();touch();render();toast('Draft created from your business fields. Review the wording.');}
    if(action==='example'){if(confirm('Replace this session with the '+t.dataset.example+' illustration? Save JSON first if needed.'))replaceProject(window.FinanceExamples(t.dataset.example));}
    if(action==='clear-storage'){localStorage.removeItem(storeKey);localStorage.removeItem(prefKey);remember=false;render();toast('Browser copy cleared. Current session remains available.');}
    if(action==='import-library')$('#library-file').click();
    if(action==='clear-library'){if(confirm('Clear the imported library? Historical roots stay, but their Mode IDs can no longer be verified.')){p.library=null;touch();render();}}
    if(action==='select-mode'){if(!p.library)throw new Error('Import the library first.');if(p.roots.filter(x=>x.lane==='historical').length>=C.SET.historical)throw new Error('Three historical modes are already selected. Remove one before selecting another.');const m=C.rankLibrary(p.library.modes).shortlist.find(m=>m.modeId===t.dataset.id);if(!m)throw new Error('That mode is not in the shortlist.');if(p.roots.some(x=>x.lane==='historical'&&x.modeId.trim()===m.modeId))throw new Error('That mode is already selected.');const x=newRoot('historical');Object.assign(x,{modeId:m.modeId,title:m.name||m.modeId,wrongInterpretation:m.mechanism,detectionMethod:m.detection,libraryRecord:JSON.stringify(m.record,null,2)});render();toast('Historical mode '+m.modeId+' added. Instantiate it for this task on Root design.');}
    if(action==='add-mode'){newRoot();tab='roots';render();}
    if(action==='open-root'){if(p.roots.some(x=>x.id===t.dataset.id)){active=t.dataset.id;tab='roots';render();}}
    if(action==='scaffold'){const n=C.scaffoldRoot(r(),catalog.mechanisms.find(m=>m.id===r().mechanism));r().reviewStatus='pending';invalidateGates();touch();render();toast(n?n+' field(s) scaffolded as hypotheses. Replace them with task-specific facts.':'No blank record field to scaffold.');}
    if(action==='draft-guidance'){const g=C.generateGuidance(p,lintOpts());p.guidance=g.text;touch();render();toast('Guidance drafted from the recorded modes ('+g.wordCount+' words). Rewrite it in your own words before use.');}
    if(action==='clean-guidance'){const c=C.cleanText(p.guidance);p.guidance=c.text;touch();render();toast(c.replacements+' replacement(s) made.');}
    if(action==='guidance-text'){if(!p.guidance.trim())throw new Error('Write or draft grader guidance first.');const blockers=C.lintGuidance(p.guidance,lintOpts()).filter(x=>x.level==='blocker').length;download(filename('grader-guidance.txt'),C.cleanText(p.guidance).text,'text/plain');toast(blockers?'Exported with '+blockers+' lint blocker(s) still open.':'Grader guidance exported.',!!blockers);}
    if(action==='modes-text')download(filename('failure-modes-PRIVATE.txt'),C.failureModeRecords(p),'text/plain');
    if(action==='working-doc')download(filename('working-document-PRIVATE.md'),C.workingDocument(p,lintOpts()),'text/markdown');
    if(action==='add-source'){p.sources.push(C.source());invalidateGates();touch();render();}
    if(action==='remove-source'){if(confirm('Remove this source and its anchor links?')){p.sources=p.sources.filter(s=>s.id!==t.dataset.id);p.roots.forEach(x=>{x.sourceIds=x.sourceIds.filter(id=>id!==t.dataset.id);x.outputs.forEach(o=>o.sourceIds=o.sourceIds.filter(id=>id!==t.dataset.id));});invalidate();touch();render();}}
    if(action==='add-root'){newRoot();render();}
    if(action==='remove-root'&&p.roots.length>1){if(confirm('Remove this failure mode? Historical run references will remain.')){p.roots=p.roots.filter(x=>x.id!==r().id);active=p.roots[0].id;invalidateGates();touch();render();}}
    if(action==='add-output'){r().outputs.push(C.output());r().reviewStatus='pending';invalidateGates();touch();render();}
    if(action==='remove-output'){r().outputs=r().outputs.filter(x=>x.id!==t.dataset.id);r().reviewStatus='pending';invalidateGates();touch();render();}
    if(action==='calculate'){p.oracle.result=C.calculate(p.oracle.kind,p.oracle.inputs);touch();render();toast('Arithmetic computed from the entered inputs.');}
    if(action==='use-calculation'){if(!p.oracle.result)throw new Error('Calculate a current result first.');const o=C.output(),z=p.oracle.result;Object.assign(o,{label:z.label,unit:z.unit,correct:String(z.value),calculation:z.formula+'\nInputs: '+JSON.stringify(p.oracle.inputs)+'\nDetails: '+JSON.stringify(z.details)+'\nLimits: '+z.caveat,sourceIds:[...r().sourceIds]});r().outputs.push(o);r().reviewStatus='pending';invalidateGates();touch();render();toast('Correct output added. Supply a wrong branch and verify input anchors.');}
    if(action==='refresh')render();
    if(action==='solver-json')download(filename('solver-draft.json'),JSON.stringify(C.solverDraft(p),null,2));
    if(action==='solver-text'){const s=C.solverDraft(p);download(filename('solver-draft.txt'),s.businessPrompt+'\n\nSupplied files (attach separately):\n'+s.suppliedFileManifest.map(x=>x.file+' — '+x.version).join('\n'),'text/plain');}
    if(action==='evaluator-json')download(filename('evaluator-draft-PRIVATE.json'),JSON.stringify(C.evaluatorDraft(p,lintOpts()),null,2));
    if(action==='evaluator-text')download(filename('evaluator-draft-PRIVATE.txt'),evaluatorText(C.evaluatorDraft(p,lintOpts())),'text/plain');
    if(action==='import-catalog')$('#catalog-file').click();
    if(action==='export-catalog')download('finance-research-catalog.json',JSON.stringify(C.catalogExport(catalog),null,2));
    if(action==='remove-run'&&confirm('Remove this observed run record?')){p.experiments=p.experiments.filter(x=>x.id!==t.dataset.id);touch();render();}
  }catch(error){toast(error.message,true);}});
  $('#project-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw new Error('Project exceeds the 5 MB import limit.');const next=C.parseProject(await file.text());if(confirm('Load this project and replace the current session?')){replaceProject(next);toast('Project loaded and structurally validated. Review source and interpretation content.');}}catch(error){toast('Import rejected: '+error.message,true);}e.target.value='';});
  $('#catalog-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw new Error('Catalog exceeds the 5 MB import limit.');const next=C.parseCatalog(await file.text());catalog=next;render();toast('Research catalog loaded for this session. Export it to keep a copy.');}catch(error){toast('Catalog rejected: '+error.message,true);}e.target.value='';});
  $('#library-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw new Error('Library exceeds the 5 MB import limit.');p.library=C.parseLibrary(await file.text());const rank=C.rankLibrary(p.library.modes);touch();render();toast('Library imported: '+p.library.modes.length+' modes returned, '+rank.eligible.length+' eligible.'+(rank.complete?'':' Fewer than ten eligible; do not pad.'),!rank.complete);}catch(error){toast('Library rejected: '+error.message,true);}e.target.value='';});
  document.addEventListener('submit',e=>{if(e.target.id!=='run-form')return;e.preventDefault();try{const f=new FormData(e.target),x={id:C.uid(),runId:f.get('runId'),date:f.get('date'),model:f.get('model'),score:f.get('score'),scoreMax:f.get('scoreMax'),evidence:f.get('evidence'),notes:f.get('notes'),classification:f.get('classification'),versions:{prompt:f.get('promptVersion'),workbook:f.get('workbookVersion'),evaluator:f.get('evaluatorVersion')},rootFailures:f.getAll('rootFailures'),snapshot:''};C.validateExperiment(x);if(p.experiments.some(y=>y.runId===x.runId))throw new Error('This run ID already exists. Use a distinct actual run or remove the duplicate.');if(f.has('attachSnapshot')){if(!Object.keys(p.versions).every(k=>p.versions[k]===x.versions[k]))throw new Error('Current snapshot cannot be attached to different version labels.');x.snapshot=C.snapshot(p);}p.experiments.push(x);touch();render();toast('Actual run record saved as entered. Evidence was not independently verified.');}catch(error){toast(error.message,true);}});
  window.addEventListener('beforeunload',e=>{if(dirty&&!remember){e.preventDefault();e.returnValue='';}});
  window.FinanceAuthoring={getProject:()=>C.clone(p),loadProject:project=>{p=C.parseProject(project);active=p.roots[0].id;tab='workspace';dirty=false;render();},showTab:id=>{if(pages.some(([key])=>key===id)){tab=id;render();}},showRoot:id=>{if(p.roots.some(x=>x.id===id)){active=id;tab='roots';render();}},
    /* Append a generated candidate root to the current project as a net-new mode. Sources are merged by file, location, and version; nothing in the current project is replaced. */
    addCandidate:(pkg,candidate)=>{const H=window.FinanceCandidates,temp=H.projectFor(pkg,candidate),map={};temp.sources.forEach(s=>{const existing=p.sources.find(x=>x.file===s.file&&x.cell===s.cell&&x.page===s.page&&x.version===s.version);const id=existing?existing.id:C.uid();map[s.id]=id;if(!existing)p.sources.push({...C.clone(s),id});});const src=temp.roots[0],ids=list=>[...new Set(list.map(id=>map[id]).filter(Boolean))];const x={...C.clone(src),id:C.uid(),lane:'net-new',modeId:'',libraryRecord:'',reviewStatus:'pending',sourceIds:ids(src.sourceIds),outputs:src.outputs.map(o=>({...C.clone(o),id:C.uid(),sourceIds:ids(o.sourceIds)}))};x.causalGroup=src.causalGroup||x.id;if(!x.correctiveAction.trim())x.correctiveAction=src.correctInterpretation;if(!x.triggeringCondition.trim())x.triggeringCondition=candidate.proposedMutation||'';p.roots.push(x);active=x.id;tab='roots';invalidateGates();touch();render();return x.id;}};
  render();
})();
